import sqlite3
import os

DB_PATH = '/data/test.db'

os.makedirs('/data', exist_ok=True)

# Remove a corrupt or non-database file so sqlite can recreate it cleanly.
if os.path.exists(DB_PATH):
    try:
        with open(DB_PATH, 'rb') as f:
            header = f.read(16)
        if header != b'SQLite format 3\x00':
            os.remove(DB_PATH)
    except (OSError, IOError):
        try:
            os.remove(DB_PATH)
        except OSError:
            pass
    else:
        try:
            os.chmod(DB_PATH, 0o644)
        except OSError:
            pass

conn = sqlite3.connect(DB_PATH)
cur = conn.cursor()
cur.execute("CREATE TABLE IF NOT EXISTS logs (id INTEGER PRIMARY KEY, message TEXT)")
cur.execute("INSERT INTO logs (message) VALUES ('boot')")
conn.commit()
conn.close()
os.chmod(DB_PATH, 0o644)
print("Log entry written.")
